using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class HouseFreightReceivingTests
{
    static readonly EntityId Home=new("site:kofu"),Source=new("site:castle"),Head=new("person:shingen"),Agent=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start()=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Head.Value,1,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:HouseFreightReceiving.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:proxy-freight-travel/"+s.Revision,node),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    static EntityId Grant(WorldSession s,int days=30){var id=new EntityId("request:proxy-freight-grant/"+s.Revision);Good(s.ManageStewardship(new(id,StewardAction.Assign,Home,Agent,Days:days,ReturnAddress:Home),s.PlayerControl,s.Revision));return id;}
    static EntityId Dispatch(WorldSession s){var id=new EntityId("request:proxy-freight/"+s.Revision);Good(s.ManageHouseFreight(new(id,HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:10,Advance:200),s.PlayerControl,s.Revision));return id;}
    static CommandResult Act(WorldSession s,HouseFreightAction a,EntityId job,EntityId? receiver=null)=>s.ManageHouseFreight(new HouseFreightInput(new("request:proxy-freight-act/"+s.Revision),a,job){Receiver=receiver},s.PlayerControl,s.Revision);
    static EntityId RoundTrip(WorldSession s){var id=Dispatch(s);Move(s,"castle");Good(Act(s,HouseFreightAction.Buy,id));Move(s,"kofu");return id;}
    static void Revoke(WorldSession s,EntityId grant)=>Good(s.ManageStewardship(new(new("request:proxy-freight-revoke/"+s.Revision),StewardAction.Revoke,Home,Grant:grant),s.PlayerControl,s.Revision));
    [Fact]public void ExplicitLocalProxyReceivesCargoAndUnusedCashIntoHouse(){var s=Start();var g=Grant(s);var id=RoundTrip(s);Good(Act(s,HouseFreightAction.Receive,id,Agent));var j=s.HouseFreightView()!.Jobs.Single();Assert.Equal(HouseFreightPhase.Completed,j.Phase);Assert.Equal(Agent,j.Receipt!.Receiver);Assert.Equal(g,j.Receipt.Grant);Assert.Equal(160,j.Receipt.Cash);Assert.Equal(10,j.Receipt.Cargo);Assert.Equal(Home,j.Receipt.Home);Assert.Equal(460,s.HouseTreasuryView()!.HouseCash);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Agent));Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),Head));}
    [Fact]public void HeadReceiptAlsoHasImmutableProofWithoutProxyGrant(){var s=Start();var id=RoundTrip(s);Good(Act(s,HouseFreightAction.Receive,id));var p=s.HouseFreightView()!.Jobs.Single().Receipt!;Assert.Equal(Head,p.Receiver);Assert.Null(p.Grant);Assert.Equal(160,p.Cash);}
    [Fact]public void UngrantedProxyCannotReceiveEvenWhenHeadIsPresent(){var s=Start();var id=RoundTrip(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id,Agent).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Good(Act(s,HouseFreightAction.Receive,id));}
    [Fact]public void ExpiredProxyCannotReceiveButOriginalHeadCan(){var s=Start();Grant(s,1);var id=RoundTrip(s);Advance(s,Math.Max(s.Seconds,86401));Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id,Agent).Code);Good(Act(s,HouseFreightAction.Receive,id,Head));}
    [Theory][InlineData(false)][InlineData(true)]public void ProxyRevocationTakesEffectAtPhysicalReceiptNotSending(bool delivered){var s=Start();var g=Grant(s);var id=RoundTrip(s);Revoke(s,g);if(delivered){Advance(s,s.Seconds+3);Assert.NotEmpty(s.DiagnosticSnapshot().Stewardship!.Receipts);Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id,Agent).Code);Good(Act(s,HouseFreightAction.Receive,id,Head));}else{Assert.Empty(s.DiagnosticSnapshot().Stewardship!.Receipts);Good(Act(s,HouseFreightAction.Receive,id,Agent));}Assert.Equal(460,s.HouseTreasuryView()!.HouseCash);}
    [Fact]public void ActualHeadDepartureSelectsPresentProxyForEligibilityButDoesNotTeleportCarrier(){var s=Start();Grant(s);var id=Dispatch(s);Move(s,"castle");var w=s.DiagnosticSnapshot();var j=s.HouseFreightView()!.Jobs.Single();var input=new HouseFreightInput(new("request:proxy-eligibility"),HouseFreightAction.Receive,id);var p=HouseFreightReceiving.Prepare(w,input,j,s.Seconds,s.Revision+1);Assert.Equal(Agent,p.Receiver);Assert.NotNull(p.Grant);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(input,s.PlayerControl,s.Revision).Code);Assert.Equal(200,s.HouseFreightView()!.Jobs.Single().Cash);}
    [Fact]public void AbsentHeadAndExpiredProxyHaveNoEligibleReceiver(){var s=Start();Grant(s,1);var id=Dispatch(s);Move(s,"castle");Advance(s,Math.Max(s.Seconds,86401));Assert.Throws<InvalidDataException>(()=>HouseFreightReceiving.Prepare(s.DiagnosticSnapshot(),new(new("request:no-proxy-eligibility"),HouseFreightAction.Receive,id),s.HouseFreightView()!.Jobs.Single(),s.Seconds,s.Revision+1));}
    [Fact]public void ReceiverSelectionCannotBeAddedToDispatchOrPurchase(){var s=Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new HouseFreightInput(new("request:fake-dispatch-receiver"),HouseFreightAction.Dispatch,Home:Home,Source:Source,Commodity:"wood",Quantity:10,Advance:200){Receiver=Agent},Head,s.Revision).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ForgedReceiverGrantOrCashProofCannotLoad(int part){var s=Start();Grant(s);var id=RoundTrip(s);Good(Act(s,HouseFreightAction.Receive,id,Agent));var w=s.DiagnosticSnapshot();w.HouseFreight=w.HouseFreight! with{Entries=w.HouseFreight.Entries.Select(e=>e.Receipt==null?e:e with{Receipt=part==0?e.Receipt with{Receiver=Head}:part==1?e.Receipt with{Grant=null}:e.Receipt with{Cash=999}}).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldV10ReceiptsRemainByteIdenticalAndRejectProxyFields(){var s=HouseLogisticsTests.Start();var id=new EntityId("request:legacy-v10-freight");Good(s.ManageHouseFreight(new(id,HouseFreightAction.Dispatch,Home:new("site:castle"),Source:Home,Commodity:"wood",Quantity:1,Advance:100),s.PlayerControl,s.Revision));Good(Act(s,HouseFreightAction.Receive,id));var b=ContractJson.Write(s.DiagnosticSnapshot());var fields=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().HouseFreight));Assert.DoesNotContain("\"Receiver\"",fields);Assert.DoesNotContain("\"Receipt\"",fields);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ActualGenerationRecoveryPreservesProxyReceiptAndPhysicalCancellation(int phase){var a=Start();var g=Grant(a);var id=RoundTrip(a);if(phase==1)Good(Act(a,HouseFreightAction.Receive,id,Agent));if(phase==2){Revoke(a,g);Advance(a,a.Seconds+3);}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"proxy-freight-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"proxy-freight",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("proxy-freight"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.HouseFreightView()),ContractJson.Write(b.HouseFreightView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"proxy-freight-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"proxy-freight-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){if(phase==0)Good(Act(s,HouseFreightAction.Receive,id,Agent));if(phase==2){Assert.Equal(ResultCode.NotAvailable,Act(s,HouseFreightAction.Receive,id,Agent).Code);Good(Act(s,HouseFreightAction.Receive,id,Head));}Advance(s,s.Seconds+3*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Fact]public void NormalCampaignProfileUsesExplicitProxyVersionWithoutMigratingOldSaves(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"proxy-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Head.Value,1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,HouseFreightReceiving.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.True(HouseFreightReceiving.Enabled(s.DiagnosticSnapshot()));Grant(s);var id=Dispatch(s);Good(Act(s,HouseFreightAction.Receive,id,Agent));Assert.Equal(Agent,s.HouseFreightView()!.Jobs.Single().Receipt!.Receiver);}
}
